if command -v dsh-acp >/dev/null 2>&1 && command -v node >/dev/null 2>&1 && node -e 'const [major, minor] = process.versions.node.split(".").map(Number); process.exit(major > 24 || (major === 24 && minor >= 9) ? 0 : 1)' && { reported="$(dsh-acp --version 2>/dev/null)" || reported=; case "$reported" in 'dsh-acp '*) reported="${reported#dsh-acp }" ;; *) reported= ;; esac; major="${reported%%.*}"; rest="${reported#*.}"; minor="${rest%%.*}"; case "$major" in ''|*[!0-9]*) major= ;; esac; case "$minor" in ''|*[!0-9]*) minor= ;; esac; [ -n "$major" ] && [ -n "$minor" ] && { [ "$major" -gt 0 ] || { [ "$major" -eq 0 ] && [ "$minor" -ge 8 ]; }; }; }; then set -- dsh-acp; elif [ -x '/opt/mj-harnesses/harnesses/dsh/dsh-acp-0.8.0/dsh-acp' ] && command -v node >/dev/null 2>&1 && node -e 'const [major, minor] = process.versions.node.split(".").map(Number); process.exit(major > 24 || (major === 24 && minor >= 9) ? 0 : 1)'; then set -- '/opt/mj-harnesses/harnesses/dsh/dsh-acp-0.8.0/dsh-acp'; elif command -v node >/dev/null 2>&1 && node -e 'const [major, minor] = process.versions.node.split(".").map(Number); process.exit(major > 24 || (major === 24 && minor >= 9) ? 0 : 1)' && command -v npm >/dev/null 2>&1 && command -v npx >/dev/null 2>&1; then set -- npx -y @brokkai/dsh-acp@0.8.0; else echo 'Mjolnir requires dsh-acp 0.8.0 or newer with Node.js 24.9.0+; install or upgrade dsh-acp, Node.js, npm, and npx in the target environment' >&2; exit 127; fi; if [ -z "${DSH_ACP_DATA_DIR:-}" ]; then echo 'Mjolnir requires DSH_ACP_DATA_DIR to keep dsh-acp sessions outside the workspace' >&2; exit 1; fi; DSH_ACP_DSH_HOME="${DSH_ACP_DATA_DIR}/dsh-home"; export DSH_ACP_DSH_HOME; DSH_ACP_SYSTEM_PROMPT=; export DSH_ACP_SYSTEM_PROMPT; exec "$@"